def first_Element(arr, n, k):
    """Write a python function to find the first element occurring k times in a given array."""
    if k <= 0:
        return -1
    counts = {}
    for i in range(min(n, len(arr))):
        counts[arr[i]] = counts.get(arr[i], 0) + 1
        if counts[arr[i]] == k:
            return arr[i]
    return -1
